//! 资源文档链接
//!
//! 勾画语句中指向项目内文件的资源引用, 与识别层共用同一份判定:
//! 遍历 [`candidate_offsets`] 给出的候选位置, 交由 [`recognize_ident`] 判定,
//! 只保留资源类型的标识符.
//!
//! # Behavior
//! * 仅为项目中**真实存在**的资源生成链接 (缺失资源交由诊断提示, 避免死链);
//! * 存在性检查只使用项目本地维护的 [`Resource`](crate::project::Resource), 不访问文件系统.

use derive_more::{Deref, Into, IntoIterator};
use lsp_types::*;
use path_tree::{canonicalize, join, name_of};
use webgal_language_core::{
    resource::{FigureKind, ResourceKind},
    util::span_of,
};

use crate::project::Project;

use super::recognize::{Ident, candidate_offsets, recognize_ident};

/// 文档链接能力
pub fn document_link_capability() -> DocumentLinkOptions {
    DocumentLinkOptions {
        // 链接信息 (区间 / 目标 / 提示) 由请求直接给出, 无需 resolve
        resolve_provider: Some(false),
        work_done_progress_options: Default::default(),
    }
}

/// 资源链接列表
///
/// 每个元素为资源类型, 资源相对项目根的路径 (形如 `background/bg.png`) 及语句内区间.
#[derive(Debug, Clone, Default, Eq, PartialEq, Into, IntoIterator, Deref)]
pub struct DocumentLinkList(Vec<(ResourceKind, String, Range)>);

impl DocumentLinkList {
    /// 转为 LSP 文档链接
    ///
    /// # Behavior
    /// * 目标为项目内的资源文件 (路径无法解析为 URI 时目标为空, 链接退化为纯提示);
    /// * 提示为资源类型与文件名.
    pub fn to_links(&self, project_root: &str) -> Vec<DocumentLink> {
        self.iter()
            .map(|(kind, path, range)| DocumentLink {
                range: *range,
                target: join(project_root, path).parse().ok(),
                tooltip: Some(format!("{}资源: {}", kind_label(*kind), name_of(path))),
                data: None,
            })
            .collect()
    }
}

/// 收集场景中出现的资源链接
///
/// # Returns
/// 场景不存在时返回 `None`.
pub fn document_links(scene_path: &str, project: &Project) -> Option<DocumentLinkList> {
    let scene = project.resource().scene.get(scene_path)?.as_item()?;
    let mut links = Vec::new();

    for (line, info) in scene.sentences().iter().enumerate() {
        for offset in candidate_offsets(info) {
            let position = Position {
                line: line as u32,
                character: offset as u32,
            };
            let Some(Ident::Resource(kind, name)) = recognize_ident(scene_path, position, project)
            else {
                continue;
            };
            let Some(path) = resource_file(project, kind, name) else {
                continue;
            };

            // 链接区间为标识符自身的名称区间
            let span = span_of(info.content, name);
            links.push((
                kind,
                path,
                Range {
                    start: Position {
                        line: line as u32,
                        character: span.start as u32,
                    },
                    end: Position {
                        line: line as u32,
                        character: span.end as u32,
                    },
                },
            ));
        }
    }

    // 分支目标等位置可能被重复识别, 去重时保留首次出现
    links.dedup();
    Some(DocumentLinkList(links))
}

// -------- 资源解析 --------

/// 解析资源文件在项目内的路径
///
/// # Arguments
/// * **kind** - 资源类型.
/// * **name** - 识别层给出的资源名称 (立绘可能带 `?type=` 后缀, 动画不含 `.json`).
///
/// # Returns
/// 规范化为相对项目根的路径 (形如 `animation/fadeIn.json`); 资源不存在时返回 `None`.
///
/// # Behavior
/// * 名称先经 [`canonicalize`] 规范化 (`./` / 路径分隔符等);
/// * 存在性检查只使用项目本地维护的资源表, 不访问文件系统.
fn resource_file(project: &Project, kind: ResourceKind, name: &str) -> Option<String> {
    let root = kind_root(kind)?;
    if name.is_empty() {
        return None;
    }

    // 立绘资源可能带有 `?type=` 后缀
    let name = match kind {
        ResourceKind::Figure => FigureKind::from_path(name).1,
        _ => name,
    };
    // 规范化后为空 (如 `.`) 的路径不指向任何文件
    let file = canonicalize(name).filter(|file| !file.is_empty())?;

    let resource = project.resource();
    let exists = match kind {
        ResourceKind::Scene => resource.scene.contains(&file),
        ResourceKind::Animation => resource.contains_animation(&file),
        ResourceKind::Figure => resource.get_figure_redirected(&file).is_some(),
        ResourceKind::Background => resource.background.contains(&file),
        ResourceKind::Bgm => resource.bgm.contains(&file),
        ResourceKind::Vocal => resource.vocal.contains(&file),
        ResourceKind::Video => resource.video.contains(&file),
        // 配置与未知类型不会出现在语句中
        ResourceKind::Config | ResourceKind::Other => false,
    };
    if !exists {
        return None;
    }

    // 动画在动画目录下的实际位置带有 `.json` 后缀
    let file = match kind {
        ResourceKind::Animation => format!("{file}.json"),
        _ => file,
    };
    Some(format!("{root}/{file}"))
}

/// 资源类型对应的资源根目录
///
/// # Behavior
/// 与 [`ResourceKind::from_path`] 互逆. 配置与未知类型不属于语句内引用的资源, 返回 `None`.
fn kind_root(kind: ResourceKind) -> Option<&'static str> {
    Some(match kind {
        ResourceKind::Scene => "scene",
        ResourceKind::Animation => "animation",
        ResourceKind::Background => "background",
        ResourceKind::Figure => "figure",
        ResourceKind::Bgm => "bgm",
        ResourceKind::Vocal => "vocal",
        ResourceKind::Video => "video",
        ResourceKind::Config | ResourceKind::Other => return None,
    })
}

/// 资源类型的中文名称
fn kind_label(kind: ResourceKind) -> &'static str {
    match kind {
        ResourceKind::Config => "配置",
        ResourceKind::Scene => "场景",
        ResourceKind::Animation => "动画",
        ResourceKind::Background => "背景",
        ResourceKind::Figure => "立绘",
        ResourceKind::Bgm => "音乐",
        ResourceKind::Vocal => "语音",
        ResourceKind::Video => "视频",
        ResourceKind::Other => "资源",
    }
}

#[cfg(test)]
mod tests {
    use webgal_language_core::resource::Config;

    use super::*;

    /// 构建测试项目: (相对项目根的文件路径, 文件内容)
    fn project(files: &[(&str, &str)]) -> Project {
        let mut project = Project::new(Config::default());
        for (path, content) in files {
            project.insert(path, || Ok(content.to_string())).unwrap();
        }
        project
    }

    /// 收集场景中的资源链接
    fn links(project: &Project, scene: &str) -> Vec<(ResourceKind, String, Range)> {
        document_links(scene, project)
            .unwrap_or_default()
            .into_iter()
            .collect()
    }

    /// 定位名称在场景某行中的区间
    fn scene_span(scene: &str, line: u32, name: &str) -> Range {
        let text = scene.lines().nth(line as usize).expect("行应在场景中");
        let start = text.find(name).expect("名称应在语句中") as u32;
        Range {
            start: Position {
                line,
                character: start,
            },
            end: Position {
                line,
                character: start + name.len() as u32,
            },
        }
    }

    /// 定位名称在单行场景中的区间
    fn name_span(line: &str, name: &str) -> Range {
        scene_span(line, 0, name)
    }

    /// 断言单行场景中的唯一资源链接
    ///
    /// `name` 为语句中书写的资源名 (动画不含 `.json` 后缀, 立绘可含 `?type=` 后缀).
    fn assert_single(line: &str, name: &str, resource: &str, kind: ResourceKind) {
        let project = project(&[("scene/1.txt", line), (resource, "[]")]);
        assert_eq!(
            links(&project, "1.txt"),
            vec![(kind, resource.to_string(), name_span(line, name))],
            "line: {line:?}"
        );
    }

    // -------- 主参数 --------

    #[test]
    fn collects_content_resource() {
        assert_single(
            "changeBg:bg.png;",
            "bg.png",
            "background/bg.png",
            ResourceKind::Background,
        );
        assert_single(
            "changeFigure:chara.png;",
            "chara.png",
            "figure/chara.png",
            ResourceKind::Figure,
        );
        assert_single(
            "bgm:theme.mp3;",
            "theme.mp3",
            "bgm/theme.mp3",
            ResourceKind::Bgm,
        );
        assert_single(
            "playVideo:op.mp4;",
            "op.mp4",
            "video/op.mp4",
            ResourceKind::Video,
        );
        assert_single(
            "playEffect:sfx.wav;",
            "sfx.wav",
            "vocal/sfx.wav",
            ResourceKind::Vocal,
        );
        assert_single(
            "miniAvatar:face.png;",
            "face.png",
            "figure/face.png",
            ResourceKind::Figure,
        );
        assert_single(
            "unlockCg:cg.png;",
            "cg.png",
            "background/cg.png",
            ResourceKind::Background,
        );
        assert_single(
            "unlockBgm:extra.mp3;",
            "extra.mp3",
            "bgm/extra.mp3",
            ResourceKind::Bgm,
        );
        assert_single(
            "changeScene:2.txt;",
            "2.txt",
            "scene/2.txt",
            ResourceKind::Scene,
        );
        assert_single(
            "callScene:2.txt;",
            "2.txt",
            "scene/2.txt",
            ResourceKind::Scene,
        );
    }

    // -------- 参数值 --------

    #[test]
    fn collects_argument_resource() {
        assert_single(
            "say:hello -vocal=voice.wav;",
            "voice.wav",
            "vocal/voice.wav",
            ResourceKind::Vocal,
        );
        assert_single(
            "intro:text -backgroundImage=bg.png;",
            "bg.png",
            "background/bg.png",
            ResourceKind::Background,
        );
        assert_single(
            "changeFigure:chara.png -mouthOpen=open.png;",
            "open.png",
            "figure/open.png",
            ResourceKind::Figure,
        );
    }

    #[test]
    fn collects_animation_argument_with_json_extension() {
        // 动画在动画目录下的实际位置带有 `.json` 后缀
        let line = "changeBg:bg.png -enter=fadeIn -exit=fadeOut;";
        let project = project(&[
            ("scene/1.txt", line),
            ("background/bg.png", "[]"),
            ("animation/fadeIn.json", "[]"),
            ("animation/fadeOut.json", "[]"),
        ]);

        assert_eq!(
            links(&project, "1.txt"),
            vec![
                (
                    ResourceKind::Background,
                    "background/bg.png".to_string(),
                    name_span(line, "bg.png")
                ),
                (
                    ResourceKind::Animation,
                    "animation/fadeIn.json".to_string(),
                    name_span(line, "fadeIn")
                ),
                (
                    ResourceKind::Animation,
                    "animation/fadeOut.json".to_string(),
                    name_span(line, "fadeOut")
                ),
            ]
        );
    }

    #[test]
    fn collects_set_animation_content() {
        assert_single(
            "setAnimation:fadeIn -target=fig-center;",
            "fadeIn",
            "animation/fadeIn.json",
            ResourceKind::Animation,
        );
    }

    // -------- 立绘后缀 --------

    #[test]
    fn collects_figure_with_type_suffix() {
        // 区间只覆盖标识符自身, 不含 `?type=` 修饰
        assert_single(
            "changeFigure:chara.skel?type=spine;",
            "chara.skel",
            "figure/chara.skel",
            ResourceKind::Figure,
        );
    }

    // -------- 多资源 --------

    #[test]
    fn collects_multiple_resources_in_one_line() {
        let line = "changeBg:bg.png -enter=fadeIn -unlockname=home -series=cg;";
        let project = project(&[
            ("scene/1.txt", line),
            ("background/bg.png", "[]"),
            ("animation/fadeIn.json", "[]"),
        ]);

        assert_eq!(
            links(&project, "1.txt"),
            vec![
                (
                    ResourceKind::Background,
                    "background/bg.png".to_string(),
                    name_span(line, "bg.png")
                ),
                (
                    ResourceKind::Animation,
                    "animation/fadeIn.json".to_string(),
                    name_span(line, "fadeIn")
                ),
            ]
        );
    }

    #[test]
    fn collects_links_in_line_order() {
        let scene = "changeBg:bg.png;\nbgm:theme.mp3;";
        let project = project(&[
            ("scene/1.txt", scene),
            ("background/bg.png", "[]"),
            ("bgm/theme.mp3", "[]"),
        ]);

        assert_eq!(
            links(&project, "1.txt"),
            vec![
                (
                    ResourceKind::Background,
                    "background/bg.png".to_string(),
                    scene_span(scene, 0, "bg.png")
                ),
                (
                    ResourceKind::Bgm,
                    "bgm/theme.mp3".to_string(),
                    scene_span(scene, 1, "theme.mp3")
                ),
            ]
        );
    }

    // -------- 分支选项 --------

    #[test]
    fn collects_choose_scene_target() {
        let line = "choose:去往A:2.txt|留在这里:3.txt;";
        let project = project(&[
            ("scene/1.txt", line),
            ("scene/2.txt", ""),
            ("scene/3.txt", ""),
        ]);

        assert_eq!(
            links(&project, "1.txt"),
            vec![
                (
                    ResourceKind::Scene,
                    "scene/2.txt".to_string(),
                    name_span(line, "2.txt")
                ),
                (
                    ResourceKind::Scene,
                    "scene/3.txt".to_string(),
                    name_span(line, "3.txt")
                ),
            ]
        );
    }

    #[test]
    fn ignores_choose_label_target() {
        // 标签不是资源, 不生成链接
        let scene = "label:start;\nchoose:去往A:start|留在这里:2.txt;";
        let project = project(&[("scene/1.txt", scene), ("scene/2.txt", "")]);

        assert_eq!(
            links(&project, "1.txt"),
            vec![(
                ResourceKind::Scene,
                "scene/2.txt".to_string(),
                scene_span(scene, 1, "2.txt")
            )]
        );
    }

    // -------- 边界 --------

    #[test]
    fn skips_missing_resource() {
        // 含规范化后为空 (`.`) 的路径
        let project = project(&[(
            "scene/1.txt",
            "changeBg:missing.png;\nbgm:missing.mp3;\nchangeBg:.;",
        )]);

        assert_eq!(links(&project, "1.txt"), Vec::new());
    }

    #[test]
    fn skips_non_resource_idents() {
        // 对象 ID 与变量都不是资源
        let scene = "changeFigure:chara.png -id=chara;\nsay:你好 -figureId=chara {coin};";
        let project = project(&[("scene/1.txt", scene), ("figure/chara.png", "[]")]);

        assert_eq!(
            links(&project, "1.txt"),
            vec![(
                ResourceKind::Figure,
                "figure/chara.png".to_string(),
                scene_span(scene, 0, "chara.png")
            )]
        );
    }

    #[test]
    fn missing_scene_returns_none() {
        let project = project(&[("scene/1.txt", "changeBg:bg.png;")]);
        assert!(document_links("2.txt", &project).is_none());
    }

    // -------- 链接转换 --------

    #[test]
    fn converts_to_links_with_project_root() {
        let line = "changeBg:bg.png;";
        let project = project(&[("scene/1.txt", line), ("background/bg.png", "[]")]);
        let links = document_links("1.txt", &project)
            .unwrap()
            .to_links("file:///game");

        assert_eq!(links.len(), 1);
        assert_eq!(links[0].range, name_span(line, "bg.png"));
        assert_eq!(
            links[0].target.as_ref().map(|target| target.as_str()),
            Some("file:///game/background/bg.png")
        );
        assert_eq!(links[0].tooltip.as_deref(), Some("背景资源: bg.png"));
    }
}
